// Official SApay app icon for the generated iOS project.
//
// ios/ is regenerated by `cap add ios` on every CI run, so the icon cannot be
// committed there; cap:sync runs this script after the sync. Without it the
// app ships Capacitor's default template icon.
//
// resources/AppIcon-1024.png is rendered from the approved gold monogram
// (public/icons/sapay-512.svg, PR #9) with:
//   node test/web/render-icon.cjs public/icons/sapay-512.svg mobile/resources/AppIcon-1024.png 1024
// It is 1024x1024 RGB without an alpha channel, as App Store Connect requires.
import { copyFile, readFile } from 'node:fs/promises';
import path from 'node:path';

const source = path.resolve('resources/AppIcon-1024.png');
const iconSet = path.resolve('ios/App/App/Assets.xcassets/AppIcon.appiconset');

let contents;
try {
  contents = JSON.parse(await readFile(path.join(iconSet, 'Contents.json'), 'utf8'));
} catch {
  console.error(`${iconSet}/Contents.json not found. Run npx cap add ios before npm run cap:sync.`);
  process.exit(1);
}

// Capacitor 7's template has a single universal 1024x1024 entry. Fail loudly
// if a future template changes that, rather than leaving the default icon.
const images = contents.images ?? [];
const entry = images.length === 1 && images[0].size === '1024x1024' && images[0].filename ? images[0] : undefined;
if (!entry) {
  console.error(`Unexpected AppIcon set layout in ${iconSet}/Contents.json; update configure-ios-icon.mjs.`);
  process.exit(1);
}

await copyFile(source, path.join(iconSet, entry.filename));
console.log(`Installed the SApay app icon as AppIcon.appiconset/${entry.filename}.`);
